import{_ as i,o as t,c as o,ae as s}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Constitution Compliance Checker, ADR Exception Workflow, and Tests","description":"","frontmatter":{"work_package_id":"WP02","title":"Constitution Compliance Checker, ADR Exception Workflow, and Tests","lane":"done","dependencies":["WP01"],"base_branch":"022-code-review-and-governance-process-WP01","base_commit":"bfa4895dec9e139137b85cab60b5c307a37ac4ac","created_at":"2026-03-01T13:32:34.859567+00:00","subtasks":["T007","T008","T009","T010","T011","T012"],"phase":"Phase 2 - Governance Enforcement","assignee":"","agent":"claude-haiku","shell_pid":"67174","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/022-code-review-and-governance-process/tasks/WP02-compliance-checker-and-adr-workflow.md","filePath":"specs/022-code-review-and-governance-process/tasks/WP02-compliance-checker-and-adr-workflow.md"}'),l={name:"specs/022-code-review-and-governance-process/tasks/WP02-compliance-checker-and-adr-workflow.md"};function a(n,e,c,r,d,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="work-package-prompt-wp02-constitution-compliance-checker-adr-exception-workflow-and-tests" tabindex="-1">Work Package Prompt: WP02 - Constitution Compliance Checker, ADR Exception Workflow, and Tests <a class="header-anchor" href="#work-package-prompt-wp02-constitution-compliance-checker-adr-exception-workflow-and-tests" aria-label="Permalink to &quot;Work Package Prompt: WP02 - Constitution Compliance Checker, ADR Exception Workflow, and Tests&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement a compliance checker that validates every PR against the full constitution review checklist.</li><li>Each finding references the specific constitution section.</li><li>Implement an ADR exception workflow with sunset dates and 3-approval requirement.</li><li>Comprehensive tests for both the compliance checker and ADR workflow.</li></ul><p>Success criteria:</p><ul><li>PRs that violate constitution requirements are flagged with specific section references.</li><li>File size &gt; 500 lines is detected as a violation.</li><li>Missing tests for new code is detected.</li><li>ADRs without sunset dates are rejected.</li><li>ADRs with 3 approvals and sunset dates are accepted.</li><li>Governance log is updated on merge.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/022-code-review-and-governance-process/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/022-code-review-and-governance-process/spec.md</code></li><li>WP01 output: branch protection, GCA/CodeRabbit configs, governance log.</li></ul><p>Constraints:</p><ul><li>Compliance checker must read the constitution dynamically (amendments reflected immediately).</li><li>Each finding must include remediation hint and constitution section reference.</li><li>ADR exceptions must be time-bounded with sunset dates.</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t007-implement-constitution-compliance-checker" tabindex="-1">Subtask T007 - Implement constitution compliance checker <a class="header-anchor" href="#subtask-t007-implement-constitution-compliance-checker" aria-label="Permalink to &quot;Subtask T007 - Implement constitution compliance checker&quot;">​</a></h3><ul><li>Purpose: Validate every PR changeset against the full constitution review checklist to catch violations before merge.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/compliance-checker.ts</code>.</li><li>Read the constitution from <code>docs/reference/constitution.md</code> at runtime (not hardcoded) so amendments are reflected immediately.</li><li>Parse the review checklist sections from the constitution. Map each section to a programmable check: <ul><li><strong>Correctness</strong>: verify new functions have return type annotations; verify no unreachable code.</li><li><strong>Tests</strong>: verify every new/modified source file has a corresponding test file or test additions.</li><li><strong>Types</strong>: verify no <code>any</code> type usage; verify strict null checks are respected.</li><li><strong>Error handling</strong>: verify try/catch blocks have specific error types; verify no swallowed errors.</li><li><strong>Performance</strong>: verify no unbounded loops or synchronous I/O in hot paths.</li><li><strong>Security</strong>: verify no hardcoded secrets, credentials, or API keys in source.</li><li><strong>File size</strong>: verify no file exceeds 500 lines.</li><li><strong>Anti-patterns</strong>: verify no circular imports; verify single-responsibility principle.</li></ul></li><li>Accept a PR diff or file list as input (from CI context or local invocation).</li><li>For each check, produce a finding with: check name, file path, line number (where applicable), violation description, constitution section reference, and remediation hint.</li><li>Output findings as structured JSON conforming to the gate report schema.</li><li>Exit 0 if all checks pass; exit 1 if any violations found.</li><li>Support <code>--json</code> and table output modes.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/compliance-checker.ts</code></li></ul></li><li>Acceptance: <ul><li>All constitution review checklist items have corresponding checks.</li><li>Findings include constitution section references.</li><li>Dynamic constitution reading works.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-implement-constitution-section-referencing" tabindex="-1">Subtask T008 - Implement constitution section referencing <a class="header-anchor" href="#subtask-t008-implement-constitution-section-referencing" aria-label="Permalink to &quot;Subtask T008 - Implement constitution section referencing&quot;">​</a></h3><ul><li>Purpose: Link each compliance finding to the specific section in the constitution for easy lookup and dispute resolution.</li><li>Steps: <ol><li>Parse the constitution markdown to extract section headings and their line numbers.</li><li>Map each compliance check to its corresponding constitution section by heading match.</li><li>Include in each finding: <code>constitutionSection</code> (heading text), <code>constitutionLine</code> (line number in constitution file).</li><li>Format the reference as a clickable link in GitHub PR comments: <code>[Constitution: Section Name](docs/reference/constitution.md#L&lt;line&gt;)</code>.</li><li>Handle constitution amendments: if a mapped section heading changes, log a warning and fall back to &quot;Section not found&quot; rather than crashing.</li><li>Test: verify each check produces a valid section reference.</li><li>Test: rename a constitution section, verify the checker handles it gracefully.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/compliance-checker.ts</code> (integration)</li></ul></li><li>Acceptance: <ul><li>Every finding includes a constitution section reference.</li><li>References are formatted as clickable links.</li><li>Graceful handling of constitution changes.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t009-create-compliance-check-github-action" tabindex="-1">Subtask T009 - Create compliance check GitHub Action <a class="header-anchor" href="#subtask-t009-create-compliance-check-github-action" aria-label="Permalink to &quot;Subtask T009 - Create compliance check GitHub Action&quot;">​</a></h3><ul><li>Purpose: Run the compliance checker automatically on every PR as a required status check.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/.github/workflows/compliance-check.yml</code>.</li><li>Trigger on <code>pull_request</code> events (opened, synchronize, reopened).</li><li>Check out the PR branch and the constitution file.</li><li>Run the compliance checker against the PR diff.</li><li>Post findings as a PR comment with structured formatting.</li><li>Set the status check result based on checker exit code.</li><li>If the checker finds violations, include the full findings in the PR comment with constitution references.</li><li>If the checker passes, post a compliance attestation comment.</li><li>Ensure the status check blocks merge on failure.</li><li>Configure timeout: 2 minutes for the compliance check.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/.github/workflows/compliance-check.yml</code></li></ul></li><li>Acceptance: <ul><li>Action triggers on PR events.</li><li>Findings posted as PR comment.</li><li>Status check blocks merge on violations.</li><li>Completes in &lt; 2 minutes.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t010-implement-adr-exception-workflow" tabindex="-1">Subtask T010 - Implement ADR exception workflow <a class="header-anchor" href="#subtask-t010-implement-adr-exception-workflow" aria-label="Permalink to &quot;Subtask T010 - Implement ADR exception workflow&quot;">​</a></h3><ul><li>Purpose: Provide a structured process for documenting and approving exceptions to constitution rules.</li><li>Steps: <ol><li>Create the ADR directory: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/docs/adrs/</code>.</li><li>Create an ADR template at <code>docs/adrs/TEMPLATE.md</code> with required fields: title, status (proposed/accepted/superseded), date, constitution section being excepted, justification, sunset date or permanence justification, required approvers (3).</li><li>Implement ADR validation logic in the compliance checker: <ul><li>When a PR violates a constitution rule, check if a linked ADR exists in the PR that documents the exception.</li><li>Validate the ADR has: a sunset date OR explicit permanence justification, at least 3 approvals (from PR review comments or ADR file metadata).</li><li>If the ADR is valid, accept the exception and note it in the compliance report.</li><li>If the ADR is invalid (missing sunset date, insufficient approvals), reject the exception.</li></ul></li><li>When a PR with a valid exception is merged, record the ADR in the governance log entry.</li><li>Implement ADR expiry tracking: a CI check that scans <code>docs/adrs/</code> for ADRs past their sunset date and alerts.</li><li>Test: PR with violation + valid ADR + 3 approvals -&gt; compliance passes with exception noted.</li><li>Test: PR with violation + ADR missing sunset date -&gt; compliance fails.</li><li>Test: PR with violation + no ADR -&gt; compliance fails.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/docs/adrs/TEMPLATE.md</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/compliance-checker.ts</code> (ADR integration)</li></ul></li><li>Acceptance: <ul><li>ADR template has all required fields.</li><li>Compliance checker validates ADR exceptions correctly.</li><li>Missing sunset dates are rejected.</li><li>Valid exceptions are recorded in governance log.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t011-compliance-checker-unit-tests" tabindex="-1">Subtask T011 - Compliance checker unit tests <a class="header-anchor" href="#subtask-t011-compliance-checker-unit-tests" aria-label="Permalink to &quot;Subtask T011 - Compliance checker unit tests&quot;">​</a></h3><ul><li>Purpose: Verify the compliance checker catches all constitution violation types correctly.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/compliance-checker.test.ts</code>.</li><li>Test: file exceeding 500 lines is flagged with file size constitution reference.</li><li>Test: new source file without corresponding test file is flagged.</li><li>Test: <code>any</code> type usage is flagged with types constitution reference.</li><li>Test: swallowed error (empty catch block) is flagged.</li><li>Test: hardcoded secret pattern (e.g., <code>API_KEY = &quot;sk-...&quot;</code>) is flagged.</li><li>Test: clean PR with all requirements met passes compliance.</li><li>Test: compliance attestation is generated for passing PRs.</li><li>Test: constitution section references are valid and formatted correctly.</li><li>Test: dynamic constitution reading picks up simulated amendments.</li><li>Use fixture files for each test case.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/compliance-checker.test.ts</code></li></ul></li><li>Acceptance: <ul><li>All violation types tested.</li><li>All tests pass.</li><li>Tests are deterministic.</li></ul></li><li>Parallel: Yes (after T007 is functional).</li></ul><h3 id="subtask-t012-adr-workflow-tests" tabindex="-1">Subtask T012 - ADR workflow tests <a class="header-anchor" href="#subtask-t012-adr-workflow-tests" aria-label="Permalink to &quot;Subtask T012 - ADR workflow tests&quot;">​</a></h3><ul><li>Purpose: Verify the ADR exception workflow enforces all requirements correctly.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/adr-workflow.test.ts</code>.</li><li>Test: ADR with sunset date and 3 approvals is accepted as a valid exception.</li><li>Test: ADR without sunset date (and no permanence justification) is rejected.</li><li>Test: ADR with sunset date but only 2 approvals is rejected.</li><li>Test: ADR with explicit permanence justification (no sunset date) is accepted.</li><li>Test: merged PR with valid exception produces governance log entry containing the ADR reference.</li><li>Test: expired ADR (past sunset date) is detected by the expiry tracker.</li><li>Use fixture ADR files and simulated PR contexts.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/adr-workflow.test.ts</code></li></ul></li><li>Acceptance: <ul><li>All ADR scenarios covered.</li><li>Governance log integration verified.</li><li>Tests are deterministic.</li></ul></li><li>Parallel: Yes (after T010 is functional).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Fixture-based compliance checker tests with deliberate violations.</li><li>ADR fixture files for exception workflow testing.</li><li>Constitution section reference validation.</li><li>Governance log integration verified via test merges.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: Constitution format changes break the parser.</li><li>Mitigation: Parser handles missing sections gracefully; unit tests verify robustness.</li><li>Risk: ADR approval count is hard to verify programmatically.</li><li>Mitigation: Use PR review comment count or ADR file metadata; document the verification method.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm all constitution checklist items have corresponding checks.</li><li>Confirm findings include constitution section references with line numbers.</li><li>Confirm ADR exceptions require sunset dates and 3 approvals.</li><li>Confirm governance log entries are created for merges with exceptions.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:32:35Z – claude-haiku – shell_pid=67174 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:34:02Z – claude-haiku – shell_pid=67174 – lane=done – Implemented</li></ul>',32)])])}const m=i(l,[["render",a]]);export{h as __pageData,m as default};
